// 27-tap direct-form FIR, 8-bit samples, unpipelined MAC cone (the long
// register-to-register path is the critical path, roughly independent of
// the tap count -> high Fmax). Same transfer function as the reference (the
// "short" path) plus a tiny amount of extra delay, to see whether it stably
// tracks the reference (the "long" path). Same transfer function as the
// reference + a tiny extra (fixed, independent of the tap function) -> the
// long path asymptotically tracks the short path exactly.
module firr27_v3 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [7:0]  x,
    output reg  [15:0] y
);
    reg  [7:0]  xs [0:26];
    integer     i;
    reg  [23:0] acc;
    always @(*) acc = 8'd1 * xs[0] + 8'd3 * xs[1] + 8'd7 * xs[2] + 8'd13 * xs[3] + 8'd21 * xs[4] + 8'd31 * xs[5] + 8'd43 * xs[6] + 8'd57 * xs[7] + 8'd73 * xs[8] + 8'd91 * xs[9] + 8'd111 * xs[10] + 8'd133 * xs[11] + 8'd157 * xs[12] + 8'd183 * xs[13] + 8'd211 * xs[14] + 8'd241 * xs[15] + 8'd273 * xs[16] + 8'd307 * xs[17] + 8'd343 * xs[18] + 8'd381 * xs[19] + 8'd421 * xs[20] + 8'd463 * xs[21] + 8'd507 * xs[22] + 8'd553 * xs[23] + 8'd601 * xs[24] + 8'd651 * xs[25] + 8'd703 * xs[26];
    always @(posedge clk) begin
        if (!rst_n) begin
            for (i = 0; i < 27; i = i + 1) xs[i] <= 8'd0;
            y <= 16'd0;
        end else begin
            xs[0] <= x;
            for (i = 1; i < 27; i = i + 1) xs[i] <= xs[i-1];
            y <= acc[15:0];
        end
    end
endmodule
